// 1. Trigger Marker Highlight Underline after page load
window.addEventListener('DOMContentLoaded', () => {
    setTimeout(() => {
        const marker = document.getElementById('hero-highlight');
        if (marker) marker.classList.add('drawn');
    }, 300);

    initEmailPreviews();
    startTypewriter();
});

// Keep the supplied email sources intact for the iframe previews.
const emailSources = [
    '',
    '',
].map(encoded => new TextDecoder().decode(Uint8Array.from(atob(encoded), character => character.charCodeAt(0))));

function buildEmailDocument(source) {
    const fitStyles = `<style>
        html, body { margin: 0; }
        img { max-width: 100%; }
        .container { width: 100% !important; max-width: 660px !important; table-layout: fixed; }
        td:has(> .container) { padding: 0 !important; }
        @media (max-width: 540px) {
            .px-mobile { padding-left: 16px !important; padding-right: 16px !important; }
        }
    </style>`;
    if (source.includes('</head>')) return source;
    return '<!doctype html><html lang="en"><head><meta charset="utf-8">' +
        '<meta name="viewport" content="width=device-width, initial-scale=1">' +
        fitStyles + '</head><body>' + source + '</body></html>';
}

function initEmailPreviews() {
    emailSources.forEach((source, index) => {
        const frame = document.getElementById('email-iframe-' + (index + 1));
        frame.srcdoc = buildEmailDocument(source).replace('</head>', `
            <style>
                html { overflow-y: auto; scrollbar-width: none; }
                html::-webkit-scrollbar, body::-webkit-scrollbar { display: none; }
            </style></head>`);
        // Keep Morningmate just above its 660px mobile breakpoint before scaling.
        const emailWidth = index === 1 ? 680 : 660;
        frame.style.width = emailWidth + 'px';
        const slot = frame.parentElement;
        const fitThumbnail = () => {
            const scale = Math.min(slot.clientWidth / emailWidth, 1);
            if (!scale) return;
            frame.style.transform = 'scale(' + scale + ')';
            frame.style.height = Math.ceil(slot.clientHeight / scale) + 'px';
        };
        new ResizeObserver(fitThumbnail).observe(slot);
        fitThumbnail();
    });
}

// 2. Hero Search Typewriter Effect
function startTypewriter() {
    const el = document.getElementById('typewriter-text');
    if (!el || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

    const phrases = isVietnamese ? [
        'Ngô Thị Yến Nhi',
        'Chuyên viên Marketing',
        'Hơn 4 năm làm marketing',
        'Marketing ngành fintech',
        'Marketing B2B',
        'Viết nội dung'
    ] : [
        'Ngô Thị Yến Nhi',
        'Marketing Executive',
        '4+ Years in Marketing',
        'Fintech Marketing',
        'B2B Marketing',
        'Content Writer'
    ];
    let phraseIndex = 0;
    let characterCount = phrases[0].length;
    let deleting = true;

    function tick() {
        const phrase = phrases[phraseIndex];
        characterCount += deleting ? -1 : 1;
        el.textContent = phrase.slice(0, characterCount);

        if (deleting && characterCount === 0) {
            phraseIndex = (phraseIndex + 1) % phrases.length;
            deleting = false;
            setTimeout(tick, 200);
        } else if (!deleting && characterCount === phrase.length) {
            deleting = true;
            setTimeout(tick, 1900);
        } else {
            setTimeout(tick, deleting ? 35 : 60);
        }
    }

    setTimeout(tick, 1900);
}

// 3. Scroll Reveal Intersection Observer
const observerOptions = {
    threshold: 0.12,
    rootMargin: "0px 0px -40px 0px"
};

const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            entry.target.classList.add('active');
            // Trigger bar rise animation for SEO chart bars inside this container
            entry.target.querySelectorAll('.seo-bar').forEach(bar => {
                const targetHeight = bar.getAttribute('data-target-height');
                if (targetHeight) {
                    bar.style.height = targetHeight;
                }
            });
        }
    });
}, observerOptions);

document.querySelectorAll('.reveal, .slide-right').forEach(el => {
    observer.observe(el);
});

// Taller cards pin as their bottom comes into view, so the whole card can be read.
const projectCardObserver = new ResizeObserver(entries => {
    entries.forEach(({ target }) => {
        const height = target.offsetHeight + 'px';
        target.style.setProperty('--project-card-height', height);
        if (target.id === 'campaign-project') {
            target.parentElement.style.setProperty('--campaign-card-height', height);
        }
    });
});

document.querySelectorAll('.project-stack-card').forEach(card => {
    projectCardObserver.observe(card);
});

const emailPreviewDialog = document.getElementById('email-preview-dialog');
const expandedEmailFrame = document.getElementById('email-preview-expanded');
const emailPreviewScroll = document.getElementById('email-preview-scroll');
let emailPreviewTrigger;
let previousPageOverflow;
let expandedEmailObserver;

function openEmailPreview(index, trigger) {
    const title = index === 1 ? 'WeCMS · Cash Management' : 'Morningmate · Team Collaboration';
    document.getElementById('email-preview-title').textContent = title + (isVietnamese ? ' — Xem toàn bộ email' : ' — Full Email Preview');
    expandedEmailFrame.title = isVietnamese ? 'Email ' + title : title + ' email';
    expandedEmailFrame.classList.toggle('original-morningmate', index === 2);
    emailPreviewTrigger = trigger;
    previousPageOverflow = document.body.style.overflow;
    emailPreviewDialog.showModal();
    document.body.style.overflow = 'hidden';
    emailPreviewScroll.scrollTop = 0;
    expandedEmailFrame.srcdoc = buildEmailDocument(emailSources[index - 1]);
}

document.getElementById('email-preview-close').addEventListener('click', () => {
    emailPreviewDialog.close();
});

expandedEmailFrame.addEventListener('load', () => {
    if (!emailPreviewDialog.open || !expandedEmailFrame.hasAttribute('srcdoc')) return;
    const email = expandedEmailFrame.contentDocument;
    if (!email?.body) return;
    const resizeToEmail = () => {
        expandedEmailFrame.style.height = Math.ceil(email.body.getBoundingClientRect().height) + 'px';
    };
    expandedEmailObserver?.disconnect();
    expandedEmailObserver = new ResizeObserver(resizeToEmail);
    expandedEmailObserver.observe(email.body);
    resizeToEmail();

    // The reading pane owns the scrollbar, including wheel input over the email.
    email.addEventListener('wheel', (event) => {
        if (event.ctrlKey || !event.deltaY) return;
        event.preventDefault();
        const unit = event.deltaMode === 1 ? 16 :
            event.deltaMode === 2 ? emailPreviewScroll.clientHeight : 1;
        emailPreviewScroll.scrollTop += event.deltaY * unit;
    }, { passive: false });
    email.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') emailPreviewDialog.close();
    });
});

emailPreviewDialog.addEventListener('close', () => {
    expandedEmailObserver?.disconnect();
    expandedEmailFrame.removeAttribute('srcdoc');
    expandedEmailFrame.style.height = '';
    document.body.style.overflow = previousPageOverflow;
    emailPreviewTrigger.focus();
});

