// 6. Interactive AI Media Multi-Slide Viewer (Click + Touch Swipe)
let currentAiSlide = 0;
const aiSlideTitles = isVietnamese ? [
    "Video 01 / 03 · Quảng cáo WeCMS",
    "Video 02 / 03 · Quảng cáo song ngữ Morningmate",
    "Hình ảnh 03 / 03 · Quảng cáo mạng xã hội"
] : [
    "Video 01 / 03 · WeCMS Cash Management Ad",
    "Video 02 / 03 · Bilingual Morningmate Ad",
    "Visuals 03 / 03 · B2B Social Ad Visuals"
];

function selectAiSlide(index) {
    const total = 3;
    currentAiSlide = (index + total) % total;

    // Update Slides
    document.querySelectorAll('.ai-slide').forEach((slide, idx) => {
        const isActive = idx === currentAiSlide;
        slide.inert = !isActive;
        if (isActive) {
            slide.classList.remove('opacity-0', 'pointer-events-none', 'translate-x-8');
            slide.classList.add('opacity-100', 'translate-x-0');
        } else {
            slide.querySelector('video')?.pause();
            slide.classList.add('opacity-0', 'pointer-events-none', 'translate-x-8');
            slide.classList.remove('opacity-100', 'translate-x-0');
        }
    });

    // Update Left Tabs
    document.querySelectorAll('.ai-tab-btn').forEach((btn, idx) => {
        if (idx === currentAiSlide) {
            btn.classList.remove('bg-white/5', 'hover:bg-white/10', 'text-slate-200', 'border-white/10');
            btn.classList.add('bg-brand-blue', 'text-white', 'border-brand-blue');
        } else {
            btn.classList.add('bg-white/5', 'hover:bg-white/10', 'text-slate-200', 'border-white/10');
            btn.classList.remove('bg-brand-blue', 'text-white', 'border-brand-blue');
        }
    });

    // Update Dots
    document.querySelectorAll('.ai-dot').forEach((dot, idx) => {
        if (idx === currentAiSlide) {
            dot.classList.remove('w-2', 'bg-white/30');
            dot.classList.add('w-6', 'bg-brand-yellow');
        } else {
            dot.classList.add('w-2', 'bg-white/30');
            dot.classList.remove('w-6', 'bg-brand-yellow');
        }
    });

    // Update Screen Header Label
    const label = document.getElementById('ai-screen-label');
    if (label) label.textContent = aiSlideTitles[currentAiSlide];
    const mediaHint = document.getElementById('ai-media-hint');
    mediaHint.textContent = currentAiSlide === 2 ? mediaHint.dataset.pause : mediaHint.dataset.navigate;
}

function stepAiSlide(delta) {
    selectAiSlide(currentAiSlide + delta);
}

// Touch swipe support on AI Media viewport
const aiViewport = document.getElementById('ai-media-viewport');
if (aiViewport) {
    let touchStartX = 0;
    aiViewport.addEventListener('touchstart', (e) => {
        touchStartX = e.changedTouches[0].screenX;
    }, { passive: true });
    aiViewport.addEventListener('touchend', (e) => {
        const diff = e.changedTouches[0].screenX - touchStartX;
        if (Math.abs(diff) > 40) {
            stepAiSlide(diff < 0 ? 1 : -1);
        }
    }, { passive: true });
}

// Toast feedback

let toastTimeout;
function showToast(msg) {
    const toast = document.getElementById('toast');
    const toastMsg = document.getElementById('toast-message');
    toastMsg.textContent = msg;
    toast.classList.remove('translate-y-24', 'opacity-0');

    clearTimeout(toastTimeout);
    toastTimeout = setTimeout(() => {
        toast.classList.add('translate-y-24', 'opacity-0');
    }, 3200);
}

document.querySelectorAll('[data-toast]').forEach(link => {
    link.addEventListener('click', () => showToast(link.dataset.toast));
});

document.querySelectorAll('[data-email-preview]').forEach(button => {
    button.addEventListener('click', () => openEmailPreview(Number(button.dataset.emailPreview), button));
});

document.querySelectorAll('[data-case]').forEach(button => {
    button.addEventListener('click', () => openCaseModal(button.dataset.case));
});

document.getElementById('project-modal-close').addEventListener('click', closeModal);

document.querySelectorAll('[data-ai-tab], [data-ai-dot]').forEach(button => {
    button.addEventListener('click', () => selectAiSlide(Number(button.dataset.aiTab ?? button.dataset.aiDot)));
});

document.querySelectorAll('[data-ai-step]').forEach(button => {
    button.addEventListener('click', () => stepAiSlide(Number(button.dataset.aiStep)));
});
